const splitItems = $('Code in JavaScript3').all();
const allResults = [];

for (let i = 0; i < items.length; i++) {
  const data = items[i].json;
  const results = data.results || [];
  const concurrent = splitItems[i] ? splitItems[i].json.concurrent : "";

  for (const item of results) {
    let sourceName = "";
    if (item.url) {
      const match = item.url.match(/https?:\/\/(?:www\.)?([^\/]+)/);
      sourceName = match ? match[1] : "";
    }

    allResults.push({
      json: {
        title: item.title || (item.snippet ? item.snippet.substring(0, 100) : "Article"),
        content: item.snippet || "",
        source: sourceName,
        date: item.last_updated || "",
        url: item.url || "",
        secteur: $('Webhook').first().json.body.secteur,
        concurrents: $('Webhook').first().json.body.concurrents,
        concurrent: concurrent,
        email: $('Webhook').first().json.body.email
      }
    });
  }
}

return allResults;

const webhookData = $('Webhook').first().json.body;
const today = new Date().toLocaleDateString('fr-FR');

const results = [];

for (const item of items) {
  let parsed;
  try {
    parsed = JSON.parse(item.json.text);
  } catch (e) {
    parsed = { résumé: item.json.text, catégorie: "Inconnue", concurrent: "Non identifié", importance: 0 };
  }

  // Filtre : ignore les articles non pertinents
  if (parsed.importance === 0 || parsed.concurrent === "Non identifié") continue;

  results.push({
    json: {
      Date: today,
      Nom: webhookData.nom,
      Secteur: webhookData.secteur,
      Concurrent: parsed.concurrent,
      Catégorie: parsed.catégorie || "Inconnue",
      Résumé: parsed.résumé || "",
      Importance: parsed.importance,
      Email: webhookData.email,
      isEmpty: false
    }
  });
}

// Si aucun résultat pertinent, retourner un item vide pour ne pas bloquer le pipeline
if (results.length === 0) {
  return [{
    json: {
      Date: today,
      Nom: webhookData.nom,
      Secteur: webhookData.secteur,
      Concurrent: "Aucun",
      Catégorie: "N/A",
      Résumé: "Aucune actualité pertinente trouvée aujourd'hui.",
      Importance: 0,
      Email: webhookData.email,
      isEmpty: true
    }
  }];
}

return results;

const body = $input.first().json.body;
const concurrents = body.concurrents.split(',').map(c => c.trim());

return concurrents.map(concurrent => ({
  json: {
    concurrent: concurrent,
    nom: body.nom,
    email: body.email,
    secteur: body.secteur,
    mots_cles: body.mots_cles
  }
}));

const webhookData = $('Webhook').first().json.body;

// Vérifie si tous les items sont vides (isEmpty = true)
const isEmpty = items.every(item => item.json.isEmpty === true);

// Filtre : garde uniquement les articles pertinents
const pertinents = items.filter(item => 
  item.json.Importance > 0 && 
  item.json.Concurrent !== "Non identifié" &&
  item.json.Concurrent !== "Aucun"
);

// Groupe les résultats par concurrent
const parConcurrent = {};
for (const item of pertinents) {
  const c = item.json.Concurrent;
  if (!parConcurrent[c]) parConcurrent[c] = [];
  parConcurrent[c].push(item.json);
}

// Construit le HTML par concurrent
let resultsHtml = '';
if (isEmpty || Object.keys(parConcurrent).length === 0) {
  resultsHtml = `
    <div style="text-align:center;padding:30px;background:#f9f9f9;border-radius:8px;">
      <p style="font-size:40px;">🔍</p>
      <p style="color:#888;font-style:italic;font-size:16px;">Aucune actualité pertinente trouvée aujourd'hui pour les concurrents surveillés.</p>
      <p style="color:#aaa;font-size:13px;">Réessayez demain ou ajustez vos mots-clés de recherche.</p>
    </div>
  `;
} else {
  for (const [concurrent, articles] of Object.entries(parConcurrent)) {
    resultsHtml += `
      <div style="margin-bottom:30px;">
        <h3 style="color:#1a73e8;border-bottom:2px solid #1a73e8;padding-bottom:5px;">${concurrent}</h3>
    `;
    for (const r of articles) {
      const scoreColor = r.importance >= 7 ? '#e53935' : r.importance >= 4 ? '#fb8c00' : '#43a047';
      resultsHtml += `
        <div style="margin-bottom:15px;padding:15px;border-left:4px solid ${scoreColor};background:#f9f9f9;border-radius:4px;">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <span style="background:#e8f0fe;color:#1a73e8;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:bold;">${r.Catégorie}</span>
            <span style="background:${scoreColor};color:white;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:bold;">Score : ${r.Importance}/10</span>
          </div>
          <p style="margin-top:10px;color:#333;line-height:1.6;">${r.Résumé}</p>
        </div>
      `;
    }
    resultsHtml += `</div>`;
  }
}

const today = new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const fullHtml = `
  <div style="font-family:Arial,sans-serif;max-width:700px;margin:0 auto;">

    <!-- En-tête -->
    <div style="background:linear-gradient(135deg,#1a73e8,#0d47a1);padding:30px;border-radius:8px 8px 0 0;">
      <h1 style="color:white;margin:0;font-size:22px;">📊 Rapport de Veille Concurrentielle</h1>
      <p style="color:#bbdefb;margin:5px 0 0 0;font-size:14px;">${today}</p>
    </div>

    <!-- Infos de la veille -->
    <div style="background:#e8f0fe;padding:20px;border-left:1px solid #ddd;border-right:1px solid #ddd;">
      <table style="width:100%;font-size:14px;color:#333;">
        <tr>
          <td style="padding:5px 0;"><strong>👤 Destinataire</strong></td>
          <td style="padding:5px 0;">${webhookData.nom}</td>
        </tr>
        <tr>
          <td style="padding:5px 0;"><strong>🏭 Secteur surveillé</strong></td>
          <td style="padding:5px 0;">${webhookData.secteur}</td>
        </tr>
        <tr>
          <td style="padding:5px 0;"><strong>🏢 Concurrents suivis</strong></td>
          <td style="padding:5px 0;">${webhookData.concurrents}</td>
        </tr>
        <tr>
          <td style="padding:5px 0;"><strong>🔍 Mots-clés</strong></td>
          <td style="padding:5px 0;">${webhookData.mots_cles}</td>
        </tr>
      </table>
    </div>

    <!-- Résultats -->
    <div style="background:white;padding:25px;border:1px solid #ddd;border-top:none;">
      <h2 style="color:#1a73e8;margin-top:0;">📰 Actualités détectées</h2>
      ${resultsHtml}
    </div>

    <!-- Pied de page -->
    <div style="background:#f5f5f5;padding:15px;text-align:center;border-radius:0 0 8px 8px;border:1px solid #ddd;border-top:none;">
      <p style="color:#888;font-size:12px;margin:0;">⚡ Rapport généré automatiquement par le système de Veille IA — Value IT</p>
    </div>

  </div>
`;

return [{ json: { emailTo: webhookData.email, htmlContent: fullHtml } }];
